package com.recordroom.vinyl;

import android.content.Context;
import android.graphics.*;
import android.content.res.ColorStateList;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Listening-room settings: compact grouped rows over the current sleeve's ambient colour. */
final class SettingsPage extends FrameLayout {
    interface Actions {void open(String destination);void changed();}
    private final ThemeStore themes;private final Actions actions;private final ArrayList<Switch> switches=new ArrayList<>();
    private final ImageView cover;private final TextView currentTitle,currentArtist;
    SettingsPage(Context context,ThemeStore themes,Actions actions){super(context);this.themes=themes;this.actions=actions;setBackground(DesignSystem.ambient(context));
        LinearLayout layout=column();addView(layout,new FrameLayout.LayoutParams(-1,-1));
        LinearLayout header=row();header.setPadding(dp(14),dp(8),dp(22),dp(4));PlayerControls.Icon back=new PlayerControls.Icon(context,"back");back.setInk(Color.WHITE);back.setGlass(false);back.setContentDescription("关闭设置");back.setOnClickListener(v->actions.open("back"));header.addView(back,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView title=text("设置",30,true);LinearLayout.LayoutParams titleP=new LinearLayout.LayoutParams(0,-2,1);titleP.leftMargin=dp(12);header.addView(title,titleP);TextView edition=text("RECORD ROOM",9,true);edition.setLetterSpacing(.12f);edition.setAlpha(.55f);header.addView(edition);layout.addView(header);
        ScrollView scroll=new ScrollView(context);scroll.setClipToPadding(false);scroll.setVerticalScrollBarEnabled(false);layout.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout body=column();body.setPadding(dp(22),dp(18),dp(22),dp(34));scroll.addView(body);
        LinearLayout hero=row();hero.setPadding(dp(16),dp(16),dp(16),dp(16));hero.setBackground(DesignSystem.settingsCard(context,20));cover=new ImageView(context);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);cover.setBackground(DesignSystem.pageButton(context,12));cover.setClipToOutline(true);hero.addView(cover,new LinearLayout.LayoutParams(dp(60),dp(60)));LinearLayout captions=column();captions.setPadding(dp(16),0,0,0);TextView eyebrow=text("此刻的唱片",10,false);eyebrow.setAlpha(.6f);captions.addView(eyebrow);currentTitle=text("准备好一张唱片",17,true);currentTitle.setMaxLines(1);currentTitle.setEllipsize(android.text.TextUtils.TruncateAt.END);currentTitle.setPadding(0,dp(5),0,dp(3));captions.addView(currentTitle);currentArtist=text("整个听音空间随封面变化",11,false);currentArtist.setAlpha(.7f);captions.addView(currentArtist);hero.addView(captions,new LinearLayout.LayoutParams(0,-2,1));body.addView(hero);
        LinearLayout music=section(body,"音乐与连接");action(music,"download","导入本地音乐","从设备中选择音频文件","import");separator(music);action(music,"music","音乐账户与联动","管理账户、曲库与官方 App 播放","accounts");separator(music);action(music,"search","搜索音乐","在一个页面找到想听的歌曲","search");
        LinearLayout look=section(body,"唱机外观");action(look,"palette","唱片材质与背景","材质、封面与唱片底灯","appearance");separator(look);toggle(look,"随封面自动配色","背景、页面与盘面保持同一色调",themes.followCoverColors(),v->{themes.followCoverColors(v);actions.changed();});separator(look);action(look,"widget","桌面小组件","把唱片放到桌面","widgets");
        LinearLayout behavior=section(body,"聆听体验");toggle(behavior,"唱片与唱臂动画","保留转动、落针和翻页的仪式感",themes.motion(),v->{themes.motion(v);actions.changed();});separator(behavior);toggle(behavior,"播放时自动收起工具","让唱片留在视线中央",themes.autoHide(),v->{themes.autoHide(v);actions.changed();});separator(behavior);toggle(behavior,"保持屏幕常亮","播放时保持唱机可见",themes.keepAwake(),v->{themes.keepAwake(v);actions.changed();});separator(behavior);toggle(behavior,"落针音效","轻轻放下唱针时的声音",themes.needleSound(),themes::needleSound);separator(behavior);action(behavior,"repeat","播放模式","顺序、随机与循环","mode");separator(behavior);action(behavior,"volume","播放音量","调节唱片机内置播放音量","volume");separator(behavior);action(behavior,"sleep","睡眠定时","让音乐陪伴入睡","sleep");
        LinearLayout about=section(body,"关于唱片机");action(about,"info","操作指南","了解手势与唱机控制","help");separator(about);action(about,"lock","开源许可","软件与素材说明","licenses");TextView footer=text("唱片机 0.7.3   /   为完整专辑留一点时间",10,false);footer.setAlpha(.5f);footer.setGravity(Gravity.CENTER);footer.setPadding(0,dp(25),0,0);body.addView(footer);refreshTheme();
    }
    void update(Bitmap artwork,String title,String artist){cover.setImageBitmap(artwork);currentTitle.setText(title==null||title.isEmpty()?"准备好一张唱片":title);currentArtist.setText(artist==null||artist.isEmpty()?"整个听音空间随封面变化":artist);refreshTheme();}
    void refreshTheme(){int tint=DesignSystem.mix(DesignSystem.currentTint(getContext()),Color.WHITE,.65f);for(Switch s:switches){s.setThumbTintList(new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{Color.WHITE,0xffc4cad0}));s.setTrackTintList(new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{tint,0x60ffffff}));}invalidate();}
    private LinearLayout section(LinearLayout body,String title){TextView label=text(title,11,true);label.setAlpha(.7f);label.setLetterSpacing(.08f);label.setPadding(dp(6),dp(26),0,dp(10));body.addView(label);LinearLayout card=column();card.setBackground(DesignSystem.settingsCard(getContext(),20));card.setPadding(dp(6),dp(4),dp(6),dp(4));body.addView(card);return card;}
    private void action(LinearLayout parent,String icon,String title,String subtitle,String destination){LinearLayout line=row();line.setPadding(dp(8),dp(9),dp(8),dp(9));line.setMinimumHeight(dp(66));PlayerControls.Icon glyph=new PlayerControls.Icon(getContext(),icon);glyph.setInk(0xe6ffffff);glyph.setClickable(false);glyph.setFocusable(false);line.addView(glyph,new LinearLayout.LayoutParams(dp(40),dp(40)));line.addView(labels(title,subtitle),new LinearLayout.LayoutParams(0,-2,1));PlayerControls.Icon arrow=new PlayerControls.Icon(getContext(),"chevron");arrow.setInk(0x9cffffff);arrow.setClickable(false);arrow.setFocusable(false);line.addView(arrow,new LinearLayout.LayoutParams(dp(28),dp(40)));line.setFocusable(true);line.setContentDescription(title);line.setOnClickListener(v->actions.open(destination));parent.addView(line);}
    private interface Change {void set(boolean value);}
    private void toggle(LinearLayout parent,String title,String subtitle,boolean checked,Change change){LinearLayout line=row();line.setPadding(dp(16),dp(13),dp(14),dp(13));line.setMinimumHeight(dp(70));line.addView(labels(title,subtitle),new LinearLayout.LayoutParams(0,-2,1));Switch control=new Switch(getContext());control.setText("");control.setChecked(checked);control.setContentDescription(title);control.setMinHeight(dp(48));control.setOnCheckedChangeListener((b,value)->change.set(value));switches.add(control);line.addView(control,new LinearLayout.LayoutParams(dp(54),dp(48)));line.setOnClickListener(v->control.setChecked(!control.isChecked()));parent.addView(line);}
    private LinearLayout labels(String title,String subtitle){LinearLayout text=column();text.setPadding(dp(8),0,dp(8),0);text.addView(text(title,14,true));TextView detail=text(subtitle,10,false);detail.setAlpha(.61f);detail.setPadding(0,dp(5),0,0);text.addView(detail);return text;}
    private void separator(LinearLayout card){View line=new View(getContext());line.setBackgroundColor(0x15ffffff);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(1));p.setMargins(dp(20),0,dp(20),0);card.addView(line,p);}
    private TextView text(String value,int sp,boolean bold){TextView t=new TextView(getContext());t.setText(value);t.setTextColor(Color.WHITE);t.setTextSize(sp);t.setTypeface(Typeface.create("sans-serif",bold?Typeface.BOLD:Typeface.NORMAL));return t;}
    private LinearLayout column(){LinearLayout v=new LinearLayout(getContext());v.setOrientation(1);return v;}private LinearLayout row(){LinearLayout v=new LinearLayout(getContext());v.setGravity(Gravity.CENTER_VERTICAL);return v;}private int dp(float n){return DesignSystem.dp(getContext(),n);}
}
